begin;
truncate public.couples,public.profiles,public.operation_receipts cascade;
set local search_path=public,extensions;
select plan(15);
insert into auth.users(id,email,email_confirmed_at) values('00000000-0000-4000-8000-000000000041','media-first@example.test',now()),('00000000-0000-4000-8000-000000000042','media-partner@example.test',now()),('00000000-0000-4000-8000-000000000043','media-outsider@example.test',now());
insert into public.profiles(user_id,display_name) values('00000000-0000-4000-8000-000000000041','First'),('00000000-0000-4000-8000-000000000042','Partner');
insert into public.couples(id,name,start_date) values('10000000-0000-4000-8000-000000000041','Test','2024-01-01');
insert into public.memberships(couple_id,user_id,slot) values('10000000-0000-4000-8000-000000000041','00000000-0000-4000-8000-000000000041',1),('10000000-0000-4000-8000-000000000041','00000000-0000-4000-8000-000000000042',2);
insert into public.photos(id,couple_id,uploader_id,storage_path,event_date,bytes,format,width,height) values('40000000-0000-4000-8000-000000000041','10000000-0000-4000-8000-000000000041','00000000-0000-4000-8000-000000000041','test/ready.jpg','2024-01-01',100,'image/jpeg',24,16);
insert into public.memories(id,couple_id,creator_id,title,event_date) values('50000000-0000-4000-8000-000000000041','10000000-0000-4000-8000-000000000041','00000000-0000-4000-8000-000000000041','Test','2024-01-01');
select ok(not has_table_privilege('authenticated','public.upload_files','SELECT'),'Raw upload files are not readable');
select ok(not has_table_privilege('authenticated','public.upload_batches','SELECT'),'Raw upload batches are not readable');
select ok(not has_function_privilege('authenticated','public.reserve_upload(uuid,jsonb,uuid,text,timestamptz)','EXECUTE'),'Browser cannot bypass signed reservation handler');
select is((select count(*)::integer from storage.buckets where id in('staging','media') and not public),2,'Both media buckets are private');
select throws_ok($$insert into public.memory_photos values('10000000-0000-4000-8000-000000000099','50000000-0000-4000-8000-000000000041','40000000-0000-4000-8000-000000000041',0)$$,'23503',null,'Cross-space memory/photo association denied by FK');
select throws_ok($$update public.profiles set avatar_photo_id='40000000-0000-4000-8000-000000000041' where user_id='00000000-0000-4000-8000-000000000042'$$,'23503',null,'Avatar must be an own upload');
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000042',true);
select is((select count(*)::integer from public.photos),1,'Partner can read ready same-space photo');
select ok(private.can_read_media('test/ready.jpg'),'Ready photo path is authorized');
select ok(not private.can_read_media('test/missing.jpg'),'Unknown path does not authorize');
select ok(not private.can_stage('arbitrary/path'),'Unreserved staging path denied');
select throws_ok($$update public.photos set description='forged'$$,'42501',null,'Generic photo mutation denied');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000043',true);
select is((select count(*)::integer from public.photos),0,'Outsider sees no photos');
select ok(not private.can_read_media('test/ready.jpg'),'Outsider cannot use known storage path');
reset role;
update public.photos set state='deleting';
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000041',true);
select is((select count(*)::integer from public.photos),0,'Deleting photo immediately disappears');
select ok(not private.can_read_media('test/ready.jpg'),'Deleting path immediately denied');
reset role;
select * from finish();rollback;
